1	package content
2	
3	import (
4		"bytes"
5		"cmp"
6		"fmt"
7		"regexp"
8		"slices"
9		"strings"
10		"unicode/utf8"
11	
12		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
13		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
14	)
15	
16	// Rendered length limits (runes, worst case). They match the maxLength of the
17	// raw templates in schemas/content.schema.json; content_test.go checks that.
18	const (
19		SMSMaxChars     = 160
20		SubjectMaxChars = 80
21	)
22	
23	// Content is validated copy.
24	type Content struct {
25		SMSBody      string
26		EmailSubject string
27		EmailBody    string
28		// SMS is the pessimistic estimate: longest variable values, and Turkish
29		// letters in names and city.
30		SMS SMSInfo
31	}
32	
33	// Banned patterns. They are checked on the text with every variable filled
34	// in by a placeholder, so "{{city}}.com" is caught too. {{campaign_url}} is
35	// the one allowed link and is filled with a space.
36	var (
37		schemeRe = regexp.MustCompile(`(?i)[a-z][a-z0-9+.\-]*://|www\.`)
38		// A bare domain: dot-separated labels ending in a common TLD. Labels are
39		// Unicode-aware, so a Cyrillic lookalike such as "іnsider.com" is caught.
40		domainRe = regexp.MustCompile(`(?i)(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+` +
41			`(?:com|net|org|info|biz|io|co|ai|app|dev|me|ly|gl|to|cc|tv|xyz|link|shop|store|site|online|tr|eu|uk|de|us))(?:$|[^\p{L}\p{N}_-])`)
42		// A domain with any TLD, given away by the path that follows it, such as
43		// "evil.top/login". The TLD starts with a letter, so "10.30/11" passes.
44		domainPathRe = regexp.MustCompile(`(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+\p{L}[\p{L}\p{N}-]+/)`)
45		// What may touch {{campaign_url}}. Anything else could extend the link
46		// into another one: "{{campaign_url}}@evil.top", "{{campaign_url}}.evil.com".
47		// Before it: the start or white space, then opening punctuation.
48		// After it: closing punctuation, then white space or the end.
49		urlBeforeRe = regexp.MustCompile(`(?:^|[\s\p{Z}])[(\["'“‘«:]*$`)
50		urlAfterRe  = regexp.MustCompile(`^[.,!?;:)\]"'”’»]*(?:[\s\p{Z}]|$)`)
51		ipRe        = regexp.MustCompile(`(?:^|[^\p{N}.])(\d{1,3}(?:\.\d{1,3}){3})(?:$|[^\p{N}.])`)
52		emailRe     = regexp.MustCompile(`[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+`)
53		htmlRe      = regexp.MustCompile(`<\s*/?\s*[A-Za-z][^>]*>`)
54	)
55	
56	// ValidateJSON parses and validates content given as raw JSON.
57	func ValidateJSON(set *schema.Set, data []byte) (Content, validation.Result) {
58		doc, err := schema.Decode(bytes.NewReader(data))
59		if err != nil {
60			var res validation.Result
61			res.Error("", validation.InvalidJSON, err.Error())
62			return Content{}, res
63		}
64		return Validate(set, doc)
65	}
66	
67	// Validate checks decoded content (from schema.Decode): the schema first,
68	// then templates, banned links, emails and HTML, and the worst-case rendered
69	// length. Every problem is reported. SMS encoding and segment count are
70	// warnings only.
71	func Validate(set *schema.Set, doc any) (Content, validation.Result) {
72		var res validation.Result
73		rawTooLong := map[string]bool{}
74		if err := set.Validate(schema.Content, doc); err != nil {
75			for _, is := range schema.Issues(err, "") {
76				res.Errors = append(res.Errors, is)
77				if is.Code == validation.TooLong {
78					rawTooLong[is.Path] = true
79				}
80			}
81		}
82	
83		fields := []struct {
84			path, a, b string
85			limit      int
86		}{
87			{"/sms/body", "sms", "body", SMSMaxChars},
88			{"/email/subject", "email", "subject", SubjectMaxChars},
89			{"/email/body", "email", "body", 0},
90		}
91		var smsParts []Part
92		values := map[string]string{}
93		for _, f := range fields {
94			s, ok := lookup(doc, f.a, f.b)
95			if !ok {
96				continue // the schema already reported it
97			}
98			values[f.path] = s
99			parts, issues := Parse(s)
100			for _, is := range issues {
101				res.Error(f.path, is.Code, is.Message)
102			}
103			checkBans(&res, f.path, parts)
104			if len(issues) > 0 {
105				continue // lengths of a broken template mean nothing
106			}
107			if f.limit > 0 && !rawTooLong[f.path] {
108				if n := utf8.RuneCountInString(worstCase(parts, false)); n > f.limit {
109					res.Error(f.path, validation.RenderedTooLong, fmt.Sprintf(
110						"can render up to %d characters with the longest variable values; the limit is %d", n, f.limit))
111				}
112			}
113			if f.path == "/sms/body" {
114				smsParts = parts
115			}
116		}
117	
118		var info SMSInfo
119		if smsParts != nil {
120			info = MeasureSMS(worstCase(smsParts, true))
121			if info.Segments > 1 {
122				msg := fmt.Sprintf("%s, %d segments in the worst case", info.Encoding, info.Segments)
123				if plain := MeasureSMS(worstCase(smsParts, false)); plain.Encoding != info.Encoding {
124					msg += fmt.Sprintf(" (names or city may contain Turkish letters such as ş, ğ, ı that switch the SMS to UCS-2; without them: %s, %d segment(s))", plain.Encoding, plain.Segments)
125				}
126				res.Warn("/sms/body", validation.SMSMultiSegment, msg)
127			}
128		}
129	
130		slices.SortStableFunc(res.Errors, func(a, b validation.Issue) int { return cmp.Compare(a.Path, b.Path) })
131		if !res.OK() {
132			return Content{}, res
133		}
134		return Content{
135			SMSBody:      values["/sms/body"],
136			EmailSubject: values["/email/subject"],
137			EmailBody:    values["/email/body"],
138			SMS:          info,
139		}, res
140	}
141	
142	// checkBans reports links, email addresses and HTML in the literal text.
143	func checkBans(res *validation.Result, path string, parts []Part) {
144		text := fill(parts)
145		if urlTouched(parts) {
146			res.Error(path, validation.URLNotAllowed, "text directly next to {{campaign_url}} is not allowed; put a space around it")
147		} else if m := schemeRe.FindString(text); m != "" {
148			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m))
149		} else if m := domainRe.FindStringSubmatch(text); m != nil {
150			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("domain %q is not allowed; use {{campaign_url}}", m[1]))
151		} else if m := domainPathRe.FindStringSubmatch(text); m != nil {
152			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m[1]))
153		} else if m := ipRe.FindStringSubmatch(text); m != nil {
154			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("address %q is not allowed; use {{campaign_url}}", m[1]))
155		}
156		if m := emailRe.FindString(text); m != "" {
157			res.Error(path, validation.EmailNotAllowed, fmt.Sprintf("email address %q is not allowed", m))
158		}
159		if m := htmlRe.FindString(text); m != "" {
160			res.Error(path, validation.HTMLNotAllowed, fmt.Sprintf("HTML %q is not allowed; copy is plain text", m))
161		}
162	}
163	
164	// fill joins the parts with a placeholder for each variable: a space for
165	// {{campaign_url}}, an "x" for the others.
166	func fill(parts []Part) string {
167		var b strings.Builder
168		for _, p := range parts {
169			switch p.Var {
170			case "":
171				b.WriteString(p.Text)
172			case "campaign_url":
173				b.WriteString(" ")
174			default:
175				b.WriteString("x")
