1	package campaign
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"log/slog"
10		"math/rand/v2"
11		"strings"
12		"sync"
13		"time"
14	
15		"github.com/jackc/pgx/v5"
16		"github.com/riverqueue/river"
17		"github.com/riverqueue/river/rivertype"
18	
19		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/content"
20		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/jobs"
21		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/llm"
22		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/retry"
23		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
24		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
25		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
26		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
27	)
28	
29	// WorkerActor is the actor of transitions the generate job makes.
30	const WorkerActor = "worker"
31	
32	// Retry limits per stage (rule 5, rule 6). They are counted separately: a
33	// transport failure does not use up a validation attempt.
34	const (
35		MaxValidationAttempts = 3
36		MaxTransportRetries   = 3
37	)
38	
39	// DefaultDeltaInterval is how often streamed copy is written to the event
40	// log, per field. The worker sets it; zero writes every delta.
41	const DefaultDeltaInterval = 150 * time.Millisecond
42	
43	// Reasons in the failed event and in the audit trail.
44	const (
45		ReasonRefusal       = "refusal"
46		ReasonInvalidOutput = "invalid_output"
47		ReasonTransport     = "transport_error"
48		ReasonCancelled     = "cancelled"
49	)
50	
51	// LLM is what the generator needs from the model client. *llm.Client
52	// satisfies it.
53	type LLM interface {
54		Call(ctx context.Context, conv *llm.Conversation, onText func(string)) (llm.Response, error)
55		Model() string
56	}
57	
58	// Pool is a database with transactions. *pgxpool.Pool satisfies it.
59	type Pool interface {
60		Beginner
61		store.DB
62	}
63	
64	// Generator runs the generate job: the segment stage, then the content
65	// stage, each validated and repaired, and records every call and event.
66	type Generator struct {
67		Pool    Pool
68		Schemas *schema.Set
69		LLM     LLM
70		Now     func() time.Time // the asOf of audience counts
71		Rand    *rand.Rand       // backoff jitter; shared, so guarded by mu
72		Sleep   func(ctx context.Context, d time.Duration) error
73		// DeltaInterval batches streamed copy per field (DefaultDeltaInterval
74		// in the worker). Zero writes every delta.
75		DeltaInterval time.Duration
76		Log           *slog.Logger
77	
78		mu sync.Mutex
79	}
80	
81	// errStop means the campaign is no longer generating at the job's version
82	// (cancelled, or a newer generation started): the job stops and writes
83	// nothing more.
84	var errStop = errors.New("campaign: generation no longer current")
85	
86	// Run runs one generation. A failed generation is an outcome, written to
87	// the campaign; Run returns an error only when the job itself could not do
88	// its work (a database error, or the context ended while the campaign was
89	// still generating), so River can retry it.
90	func (g *Generator) Run(ctx context.Context, args jobs.GenerateArgs) error {
91		r := &genRun{g: g, id: args.CampaignID, version: args.Version}
92		err := r.run(ctx)
93		if errors.Is(err, errStop) {
94			return nil
95		}
96		if err != nil && ctx.Err() != nil {
97			// River cancelled the job, or the worker is shutting down. If the
98			// campaign moved on, there is nothing left to do.
99			if ok, cerr := r.current(context.WithoutCancel(ctx)); cerr == nil && !ok {
100				return nil
101			}
102		}
103		return err
104	}
105	
106	type genRun struct {
107		g       *Generator
108		id      string
109		version int
110	}
111	
112	func (r *genRun) log() *slog.Logger {
113		if r.g.Log != nil {
114			return r.g.Log
115		}
116		return slog.New(slog.DiscardHandler)
117	}
118	
119	// current reports whether the campaign is still generating at the version.
120	func (r *genRun) current(ctx context.Context) (bool, error) {
121		return store.LockGenerating(ctx, r.g.Pool, r.id, r.version)
122	}
123	
124	// write runs fn in a transaction that holds the campaign row, only while the
125	// generation is current. Otherwise it returns errStop and writes nothing.
126	func (r *genRun) write(ctx context.Context, fn func(pgx.Tx) error) error {
127		return inTx(ctx, r.g.Pool, func(tx pgx.Tx) error {
128			ok, err := store.LockGenerating(ctx, tx, r.id, r.version)
129			if err != nil {
130				return err
131			}
132			if !ok {
133				return errStop
134			}
135			return fn(tx)
136		})
137	}
138	
139	func (r *genRun) event(ctx context.Context, typ string, payload any) error {
140		return r.write(ctx, func(tx pgx.Tx) error {
141			_, err := store.InsertGenerationEvent(ctx, tx, r.id, typ, payload)
142			return err
143		})
144	}
145	
146	func (r *genRun) run(ctx context.Context) error {
147		c, err := store.GetCampaign(ctx, r.g.Pool, r.id)
148		if errors.Is(err, store.ErrNotFound) {
149			return errStop
150		}
151		if err != nil {
152			return err
153		}
154		if State(c.State) != Generating || c.Version != r.version {
155			return errStop
156		}
157		asOf := r.g.Now().UTC().Truncate(time.Microsecond)
158	
159		// Segment stage.
160		var rule segment.Rule
161		var ruleDoc any
162		var segWarnings []validation.Issue
163		out, err := r.stage(ctx, llm.NewConversation(llm.Segment, llm.SegmentTurn(c.Brief)), func(text string) validation.Result {
164			doc, derr := schema.Decode(strings.NewReader(text))
165			if derr != nil {
166				var res validation.Result
167				res.Error("", validation.InvalidJSON, "the answer is not one JSON value: "+derr.Error())
168				return res
169			}
170			var res validation.Result
171			rule, res = segment.Validate(r.g.Schemas, doc)
172			ruleDoc, segWarnings = doc, res.Warnings
173			return res
174		}, nil)
175		if err != nil || out != nil {
176			return r.finish(ctx, err, out)
177		}
178		counts, err := segment.CountAudience(ctx, r.g.Pool, rule, asOf)
179		if err != nil {
180			return err
181		}
182		description := segment.Describe(rule)
183		if err := r.event(ctx, "segment_ready", map[string]any{"rule": ruleDoc, "description": description, "counts": counts}); err != nil {
184			return err
185		}
186	
187		// Content stage, streamed.
188		var cont content.Content
189		var contWarnings []validation.Issue
190		out, err = r.stage(ctx, llm.NewConversation(llm.Content, llm.ContentTurn(c.Brief, description)), func(text string) validation.Result {
191			var res validation.Result
192			cont, res = content.ValidateJSON(r.g.Schemas, []byte(text))
193			contWarnings = res.Warnings
194			return res
195		}, r.newDeltas)
196		if err != nil || out != nil {
197			return r.finish(ctx, err, out)
198		}
199	
200		// Success: the revision, the transition and the done event together.
201		segJSON, err := json.Marshal(ruleDoc)
202		if err != nil {
203			return err
204		}
205		warnings := []validation.Issue{}
206		for _, w := range segWarnings {
207			warnings = append(warnings, validation.Issue{Path: "/segment" + w.Path, Code: w.Code, Message: w.Message})
208		}
209		for _, w := range contWarnings {
210			warnings = append(warnings, validation.Issue{Path: "/content" + w.Path, Code: w.Code, Message: w.Message})
211		}
212		warnJSON, err := json.Marshal(warnings)
213		if err != nil {
214			return err
215		}
216		return r.write(ctx, func(tx pgx.Tx) error {
217			if err := Transition(ctx, tx, Move{ID: r.id, From: Generating, To: InReview, Version: r.version, Actor: WorkerActor, Reason: "generated"}); err != nil {
218				return err
219			}
220			rev, err := store.InsertRevision(ctx, tx, store.NewRevision{
221				CampaignID: r.id, Source: "llm", Segment: segJSON,
222				SMSBody: cont.SMSBody, EmailSubject: cont.EmailSubject, EmailBody: cont.EmailBody,
223				Warnings: warnJSON, AudienceTotal: counts.Total, SMSEligible: counts.SMSEligible, EmailEligible: counts.EmailEligible,
224			})
225			if err != nil {
226				return err
227			}
228			_, err = store.InsertGenerationEvent(ctx, tx, r.id, "done", map[string]any{"revision_id": rev.ID})
229			return err
230		})
231	}
232	
233	// failure is how a stage failed: a reason and the errors to show.
234	type failure struct {
235		stage  llm.Stage
236		reason string
237		errors []validation.Issue
238	}
239	
240	// finish turns a stage result into the job's result: a failure moves the
241	// campaign to generation_failed with a failed event.
242	func (r *genRun) finish(ctx context.Context, err error, f *failure) error {
243		if err != nil {
244			return err
245		}
246		errs := f.errors
247		if errs == nil {
248			errs = []validation.Issue{}
249		}
250		r.log().Warn("generation failed", "campaign_id", r.id, "stage", f.stage, "reason", f.reason, "errors", len(errs))
251		return r.write(ctx, func(tx pgx.Tx) error {
252			if err := Transition(ctx, tx, Move{ID: r.id, From: Generating, To: GenerationFailed, Version: r.version,
253				Actor: WorkerActor, Reason: f.reason}); err != nil {
254				return err
255			}
256			_, err := store.InsertGenerationEvent(ctx, tx, r.id, "failed", map[string]any{"reason": f.reason, "stage": f.stage, "errors": errs})
257			return err
258		})
259	}
260	
261	// stage runs one stage: up to MaxValidationAttempts answers, each after up
262	// to MaxTransportRetries transport retries. validate checks an answer and
263	// keeps what it needs. deltas, if set, streams the answer's copy fields. It
264	// returns a failure, or nil when an answer was valid.
265	func (r *genRun) stage(ctx context.Context, conv *llm.Conversation, validate func(string) validation.Result,
266		deltas func(ctx context.Context, attempt int) *deltaWriter) (*failure, error) {
267		stage := conv.Stage
268		var last []validation.Issue
269		for attempt := 1; attempt <= MaxValidationAttempts; attempt++ {
270			var resp llm.Response
271			for try := 0; ; try++ {
272				if ok, err := r.current(ctx); err != nil || !ok {
273					return nil, orStop(err)
274				}
275				var dw *deltaWriter
276				var onText func(string)
277				if deltas != nil {
278					dw = deltas(ctx, attempt)
279					onText = dw.text
280				}
281				start := time.Now()
282				var err error
283				resp, err = r.g.LLM.Call(ctx, conv, onText)
284				if dw != nil {
285					if ferr := dw.flush(); ferr != nil {
286						return nil, ferr
287					}
288				}
289				if err == nil {
290					break
291				}
292				var ce *llm.CallError
293				if !errors.As(err, &ce) {
294					return nil, err // the job's context ended
295				}
296				if werr := r.record(ctx, store.LLMCall{Stage: string(stage), Attempt: attempt, Outcome: "transport_error",
297					ErrorClass: string(ce.Class), Model: r.g.LLM.Model(), LatencyMS: int(time.Since(start).Milliseconds())}); werr != nil {
298					return nil, werr
299				}
300				if dw != nil && dw.wrote {
301					// Copy was shown for a call that broke off: tell the reader
302					// to clear it.
303					if werr := r.event(ctx, "attempt_failed", map[string]any{"stage": stage, "attempt": attempt,
304						"reason": ReasonTransport, "class": ce.Class}); werr != nil {
305						return nil, werr
306					}
307				}
308				r.log().Warn("llm call failed", "campaign_id", r.id, "stage", stage, "attempt", attempt, "class", ce.Class, "status", ce.Status)
309				if !ce.Class.Retryable() || try >= MaxTransportRetries {
310					return &failure{stage: stage, reason: ReasonTransport, errors: []validation.Issue{{
311						Code: string(ce.Class), Message: fmt.Sprintf("the call to the model failed: %s", ce.Class)}}}, nil
312				}
313				delay := ce.RetryAfter
314				if delay == 0 {
315					delay = r.g.backoff(try)
316				}
317				if err := r.g.Sleep(ctx, delay); err != nil {
318					return nil, err
319				}
320			}
321	
322			row := store.LLMCall{Stage: string(stage), Attempt: attempt, StopReason: resp.StopReason, Model: resp.Model,
323				InputTokens: &resp.InputTokens, OutputTokens: &resp.OutputTokens, LatencyMS: int(resp.Latency.Milliseconds()),
324				RawOutput: resp.Text}
325			if row.Model == "" {
326				row.Model = r.g.LLM.Model()
327			}
328			var issues []validation.Issue
329			switch resp.StopReason {
330			case "refusal":
331				row.Outcome = "refusal"
332				if err := r.record(ctx, row); err != nil {
333					return nil, err
334				}
335				return &failure{stage: stage, reason: ReasonRefusal, errors: []validation.Issue{{
336					Code: "refusal", Message: "the model refused to answer"}}}, nil
337			case "max_tokens":
338				row.Outcome = "max_tokens"
339				issues = []validation.Issue{{Code: "max_tokens", Message: "the answer was cut off at the token limit; answer again with shorter copy"}}
340			default:
341				res := validate(resp.Text)
342				if res.OK() {
343					row.Outcome = "valid"
344					return nil, r.record(ctx, row)
345				}
346				row.Outcome = "invalid"
347				issues = res.Errors
348			}
349			row.ValidationErrors = issues
350			if err := r.record(ctx, row); err != nil {
351				return nil, err
352			}
353			if err := r.event(ctx, "attempt_failed", map[string]any{"stage": stage, "attempt": attempt, "errors": issues}); err != nil {
354				return nil, err
355			}
356			r.log().Warn("llm output invalid", "campaign_id", r.id, "stage", stage, "attempt", attempt, "errors", len(issues))
357			last = issues
358			conv.Repair(resp, issues)
359		}
360		return &failure{stage: stage, reason: ReasonInvalidOutput, errors: last}, nil
361	}
362	
363	func orStop(err error) error {
364		if err != nil {
365			return err
366		}
367		return errStop
368	}
369	
370	func (r *genRun) record(ctx context.Context, c store.LLMCall) error {
371		c.CampaignID = r.id
372		c.PromptVersion = llm.PromptVersion(llm.Stage(c.Stage))
373		return r.write(ctx, func(tx pgx.Tx) error { return store.InsertLLMCall(ctx, tx, c) })
374	}
375	
376	func (g *Generator) backoff(try int) time.Duration {
377		g.mu.Lock()
378		defer g.mu.Unlock()
379		return retry.Backoff(try, g.Rand)
380	}
381	
382	// deltaWriter turns streamed answer text into delta events: the new text of
383	// each copy field, at most once per DeltaInterval, and the rest on flush.
384	type deltaWriter struct {
385		r        *genRun
386		ctx      context.Context
387		attempt  int
388		interval time.Duration
389		buf      bytes.Buffer
390		sent     llm.Fields
391		last     time.Time
392		err      error
393		wrote    bool
394	}
395	
396	func (r *genRun) newDeltas(ctx context.Context, attempt int) *deltaWriter {
397		return &deltaWriter{r: r, ctx: ctx, attempt: attempt, interval: r.g.DeltaInterval, last: time.Now()}
398	}
399	
400	func (d *deltaWriter) text(s string) {
401		d.buf.WriteString(s)
402		if d.err == nil && time.Since(d.last) >= d.interval {
403			d.err = d.emit()
404		}
405	}
406	
407	func (d *deltaWriter) flush() error {
408		if d.err != nil {
409			return d.err
410		}
411		return d.emit()
412	}
413	
414	func (d *deltaWriter) emit() error {
415		d.last = time.Now()
416		cur := llm.ExtractFields(d.buf.String())
417		for _, f := range []struct {
418			name      string
419			now, sent *string
420		}{
421			{"sms.body", &cur.SMSBody, &d.sent.SMSBody},
422			{"email.subject", &cur.EmailSubject, &d.sent.EmailSubject},
423			{"email.body", &cur.EmailBody, &d.sent.EmailBody},
424		} {
425			if len(*f.now) <= len(*f.sent) || !strings.HasPrefix(*f.now, *f.sent) {
426				continue
427			}
428			if err := d.r.event(d.ctx, "delta", map[string]any{"stage": llm.Content, "attempt": d.attempt,
429				"field": f.name, "text": (*f.now)[len(*f.sent):]}); err != nil {
430				return err
431			}
432			*f.sent = *f.now
433			d.wrote = true
434		}
435		return nil
436	}
437	
438	// GenerateWorker runs generate jobs.
439	type GenerateWorker struct {
440		river.WorkerDefaults[jobs.GenerateArgs]
441		g *Generator
442	}
443	
444	// NewGenerateWorker wraps a generator as a River worker.
445	func NewGenerateWorker(g *Generator) *GenerateWorker { return &GenerateWorker{g: g} }
446	
447	// Timeout bounds one generation (both stages with all retries).
448	func (w *GenerateWorker) Timeout(*river.Job[jobs.GenerateArgs]) time.Duration {
449		return jobs.GenerateTimeout
450	}
451	
452	func (w *GenerateWorker) Work(ctx context.Context, job *river.Job[jobs.GenerateArgs]) error {
453		return w.g.Run(ctx, job.Args)
454	}
455	
456	// Inserter inserts a River job in a transaction. *river.Client[pgx.Tx]
457	// satisfies it.
458	type Inserter interface {
459		InsertTx(ctx context.Context, tx pgx.Tx, args river.JobArgs, opts *river.InsertOpts) (*rivertype.JobInsertResult, error)
460	}
461	
462	// StartGeneration moves a campaign to generating, writes its started event
463	// and enqueues the generate job, in one transaction: none of them exists
464	// without the others. It returns the job's arguments.
465	func StartGeneration(ctx context.Context, db Beginner, ins Inserter, id string, version int, actor string) (jobs.GenerateArgs, error) {
466		args, _, err := BeginGeneration(ctx, db, ins, id, version, actor)
467		return args, err
468	}
469	
470	// BeginGeneration is StartGeneration that also returns the id of the
471	// started event, so a reader can stream this generation's events only.
472	func BeginGeneration(ctx context.Context, db Beginner, ins Inserter, id string, version int, actor string) (jobs.GenerateArgs, int64, error) {
473		var args jobs.GenerateArgs
474		var started int64
475		err := inTx(ctx, db, func(tx pgx.Tx) error {
476			c, err := store.GetCampaign(ctx, tx, id)
477			if err != nil {
478				return err
479			}
480			if err := Transition(ctx, tx, Move{ID: id, From: State(c.State), To: Generating, Version: version, Actor: actor, Reason: "generate"}); err != nil {
481				return err
482			}
483			args = jobs.GenerateArgs{CampaignID: id, Version: version + 1}
484			if started, err = store.InsertGenerationEvent(ctx, tx, id, "started", map[string]any{"version": args.Version}); err != nil {
485				return err
486			}
487			_, err = ins.InsertTx(ctx, tx, args, nil)
488			return err
489		})
490		return args, started, err
491	}
492	
493	// JobCanceller cancels a River job in a transaction. *river.Client[pgx.Tx]
494	// satisfies it.
495	type JobCanceller interface {
496		JobCancelTx(ctx context.Context, tx pgx.Tx, jobID int64) (*rivertype.JobRow, error)
497	}
498	
499	// CancelWithJobs is Cancel that also cancels the campaign's unfinished
500	// generate jobs through River, in the same transaction. A running job gets
501	// its context cancelled; a queued one never starts.
502	func CancelWithJobs(ctx context.Context, db Beginner, jc JobCanceller, id string, version int, actor string) error {
503		return inTx(ctx, db, func(tx pgx.Tx) error {
504			if err := cancelTx(ctx, tx, id, version, actor); err != nil {
505				return err
506			}
507			if jc == nil {
508				return nil
509			}
510			ids, err := store.UnfinishedJobs(ctx, tx, jobs.GenerateArgs{}.Kind(), id)
511			if err != nil {
512				return err
513			}
514			for _, jobID := range ids {
515				if _, err := jc.JobCancelTx(ctx, tx, jobID); err != nil && !errors.Is(err, rivertype.ErrNotFound) {
516					return err
517				}
518			}
519			return nil
520		})
521	}
522

