1	// Command app is the single binary for every service. The first argument
2	// picks the subcommand.
3	//
4	//	app api                        serve the HTTP API (ADMIN_TOKEN, LISTEN_ADDR)
5	//	app worker                     run the River workers (LLM_MODE, see internal/llm;
6	//	                               PROVIDER_URL)
7	//	app migrate                    apply database migrations
8	//	app seed [-users N] [-seed S] [-as-of now|RFC3339] [-reset]
9	//	                               load synthetic users and events
10	//	app mockllm                    serve the fake Messages API (MOCKLLM_ADDR,
11	//	                               MOCKLLM_INVALID_FIRST); needs no database
12	//	app mockprovider               serve the fake SMS and email provider on its own
13	//	                               database (MOCKPROVIDER_DATABASE_URL, MOCKPROVIDER_*)
14	//
15	// All others need DATABASE_URL.
16	package main
17	
18	import (
19		"context"
20		"database/sql"
21		"errors"
22		"flag"
23		"fmt"
24		"log/slog"
25		"net/http"
26		"os"
27		"os/signal"
28		"syscall"
29		"time"
30	
31		"github.com/jackc/pgx/v5/pgxpool"
32		_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
33		"github.com/riverqueue/river"
34		"github.com/riverqueue/river/riverdriver/riverpgxv5"
35	
36		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/httpapi"
37		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
38		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/seed"
39		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
40	)
41	
42	func main() {
43		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
44		defer stop()
45		log := slog.New(slog.NewJSONHandler(os.Stderr, nil))
46	
47		if len(os.Args) < 2 {
48			fmt.Fprintln(os.Stderr, "usage: app <api|worker|migrate|seed|mockllm|mockprovider> [flags]")
49			os.Exit(2)
50		}
51		var err error
52		switch os.Args[1] {
53		case "api":
54			err = apiCmd(ctx, log)
55		case "worker":
56			err = workerCmd(ctx, log, os.Getenv)
57		case "mockllm":
58			err = mockllmCmd(ctx, log, os.Getenv)
59		case "mockprovider":
60			err = mockproviderCmd(ctx, log, os.Getenv)
61		case "migrate":
62			err = migrate(ctx)
63		case "seed":
64			err = seedCmd(ctx, log, os.Args[2:])
65		default:
66			err = fmt.Errorf("unknown subcommand %q", os.Args[1])
67		}
68		if err != nil {
69			log.Error("failed", "subcommand", os.Args[1], "error", err)
70			os.Exit(1)
71		}
72	}
73	
74	func databaseURL() (string, error) {
75		url := os.Getenv("DATABASE_URL")
76		if url == "" {
77			return "", errors.New("DATABASE_URL is not set")
78		}
79		return url, nil
80	}
81	
82	func apiCmd(ctx context.Context, log *slog.Logger) error {
83		cfg, err := httpapi.ConfigFromEnv(os.Getenv)
84		if err != nil {
85			return err // fail closed: no token, no explicit opt-out, no API
86		}
87		if cfg.AdminToken == "" {
88			log.Warn("ALLOW_UNAUTHENTICATED=true: the API accepts requests without a token; local development only")
89		}
90		url, err := databaseURL()
91		if err != nil {
92			return err
93		}
94		pool, err := pgxpool.New(ctx, url)
95		if err != nil {
96			return err
97		}
98		defer pool.Close()
99		schemas, err := schema.Load()
100		if err != nil {
101			return err
102		}
103		// Insert-only: the api enqueues and cancels jobs; the worker runs them.
104		rc, err := river.NewClient(riverpgxv5.New(pool), &river.Config{Logger: log})
105		if err != nil {
106			return err
107		}
108		srv := &httpapi.Server{Config: cfg, Pool: pool, Schemas: schemas, Log: log, River: rc,
109			Hub: httpapi.NewHub(ctx, pool, log)}
110		h, err := srv.Handler()
111		if err != nil {
112			return err
113		}
114		hs := &http.Server{
115			Addr:              cfg.ListenAddr,
116			Handler:           h,
117			ReadHeaderTimeout: 5 * time.Second,
118			ReadTimeout:       10 * time.Second,
119			WriteTimeout:      30 * time.Second,
120			IdleTimeout:       60 * time.Second,
121		}
122		go func() {
123			<-ctx.Done()
124			shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
125			defer cancel()
126			_ = hs.Shutdown(shutdown)
127		}()
128		log.Info("api listening", "addr", cfg.ListenAddr, "auth_required", cfg.AdminToken != "")
129		if err := hs.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
130			return err
131		}
132		return nil
133	}
134	
135	func migrate(ctx context.Context) error {
136		url, err := databaseURL()
137		if err != nil {
138			return err
139		}
140		db, err := sql.Open("pgx", url)
141		if err != nil {
142			return err
143		}
144		defer db.Close()
145		return store.Migrate(ctx, db)
146	}
147	
148	func seedCmd(ctx context.Context, log *slog.Logger, args []string) error {
149		fs := flag.NewFlagSet("seed", flag.ContinueOnError)
150		users := fs.Int("users", 5000, "number of users")
151		seedValue := fs.Int64("seed", 42, "random seed")
152		asOfFlag := fs.String("as-of", "now", `time anchor: "now" or an RFC 3339 time`)
153		reset := fs.Bool("reset", false, "delete users, events and all campaigns first, then reload")
154		if err := fs.Parse(args); err != nil {
155			return err
156		}
157		asOf := time.Now()
158		if *asOfFlag != "now" {
159			var err error
160			if asOf, err = time.Parse(time.RFC3339Nano, *asOfFlag); err != nil {
161				return fmt.Errorf("-as-of: %w", err)
162			}
163		}
164		ds, err := seed.Generate(*seedValue, asOf, *users)
165		if err != nil {
166			return err
167		}
168		url, err := databaseURL()
169		if err != nil {
