// Command app is the single binary for every service. The first argument
// picks the subcommand.
//
//	app api                        serve the HTTP API (ADMIN_TOKEN, LISTEN_ADDR)
//	app worker                     run the River workers (LLM_MODE, see internal/llm;
//	                               PROVIDER_URL)
//	app migrate                    apply database migrations
//	app seed [-users N] [-seed S] [-as-of now|RFC3339] [-reset]
//	                               load synthetic users and events
//	app mockllm                    serve the fake Messages API (MOCKLLM_ADDR,
//	                               MOCKLLM_INVALID_FIRST); needs no database
//	app mockprovider               serve the fake SMS and email provider on its own
//	                               database (MOCKPROVIDER_DATABASE_URL, MOCKPROVIDER_*)
//
// All others need DATABASE_URL.
package main

import (
	"context"
	"database/sql"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
	"github.com/riverqueue/river"
	"github.com/riverqueue/river/riverdriver/riverpgxv5"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/httpapi"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/seed"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	log := slog.New(slog.NewJSONHandler(os.Stderr, nil))

	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: app <api|worker|migrate|seed|mockllm|mockprovider> [flags]")
		os.Exit(2)
	}
	var err error
	switch os.Args[1] {
	case "api":
		err = apiCmd(ctx, log)
	case "worker":
		err = workerCmd(ctx, log, os.Getenv)
	case "mockllm":
		err = mockllmCmd(ctx, log, os.Getenv)
	case "mockprovider":
		err = mockproviderCmd(ctx, log, os.Getenv)
	case "migrate":
		err = migrate(ctx)
	case "seed":
		err = seedCmd(ctx, log, os.Args[2:])
	default:
		err = fmt.Errorf("unknown subcommand %q", os.Args[1])
	}
	if err != nil {
		log.Error("failed", "subcommand", os.Args[1], "error", err)
		os.Exit(1)
	}
}

func databaseURL() (string, error) {
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		return "", errors.New("DATABASE_URL is not set")
	}
	return url, nil
}

func apiCmd(ctx context.Context, log *slog.Logger) error {
	cfg, err := httpapi.ConfigFromEnv(os.Getenv)
	if err != nil {
		return err // fail closed: no token, no explicit opt-out, no API
	}
	if cfg.AdminToken == "" {
		log.Warn("ALLOW_UNAUTHENTICATED=true: the API accepts requests without a token; local development only")
	}
	url, err := databaseURL()
	if err != nil {
		return err
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	defer pool.Close()
	schemas, err := schema.Load()
	if err != nil {
		return err
	}
	// Insert-only: the api enqueues and cancels jobs; the worker runs them.
	rc, err := river.NewClient(riverpgxv5.New(pool), &river.Config{Logger: log})
	if err != nil {
		return err
	}
	srv := &httpapi.Server{Config: cfg, Pool: pool, Schemas: schemas, Log: log, River: rc,
		Hub: httpapi.NewHub(ctx, pool, log)}
	h, err := srv.Handler()
	if err != nil {
		return err
	}
	hs := &http.Server{
		Addr:              cfg.ListenAddr,
		Handler:           h,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	go func() {
		<-ctx.Done()
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = hs.Shutdown(shutdown)
	}()
	log.Info("api listening", "addr", cfg.ListenAddr, "auth_required", cfg.AdminToken != "")
	if err := hs.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

func migrate(ctx context.Context) error {
	url, err := databaseURL()
	if err != nil {
		return err
	}
	db, err := sql.Open("pgx", url)
	if err != nil {
		return err
	}
	defer db.Close()
	return store.Migrate(ctx, db)
}

func seedCmd(ctx context.Context, log *slog.Logger, args []string) error {
	fs := flag.NewFlagSet("seed", flag.ContinueOnError)
	users := fs.Int("users", 5000, "number of users")
	seedValue := fs.Int64("seed", 42, "random seed")
	asOfFlag := fs.String("as-of", "now", `time anchor: "now" or an RFC 3339 time`)
	reset := fs.Bool("reset", false, "delete users, events and all campaigns first, then reload")
	if err := fs.Parse(args); err != nil {
		return err
	}
	asOf := time.Now()
	if *asOfFlag != "now" {
		var err error
		if asOf, err = time.Parse(time.RFC3339Nano, *asOfFlag); err != nil {
			return fmt.Errorf("-as-of: %w", err)
		}
	}
	ds, err := seed.Generate(*seedValue, asOf, *users)
	if err != nil {
		return err
	}
	url, err := databaseURL()
	if err != nil {
		return err
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	defer pool.Close()
	loaded, err := seed.Load(ctx, pool, ds, *reset)
	if err != nil {
		return err
	}
	if !loaded {
		log.Info("seed skipped: users already present (use -reset to reload)")
		return nil
	}
	log.Info("seed loaded", "users", len(ds.Users), "events", len(ds.Events), "seed", ds.Seed, "as_of", ds.AsOf)
	return nil
}

package main

import (
	"context"
	"errors"
	"log/slog"
	"math/rand/v2"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/riverqueue/river"
	"github.com/riverqueue/river/riverdriver/riverpgxv5"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/campaign"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/delivery"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/jobs"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/llm"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/mockllm"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
)

// workerCmd runs the River client with every queue. It is the only process
// that calls Claude and the provider (PROVIDER_URL). It fails closed before
// touching the database: an unknown LLM_MODE, LLM_MODE=anthropic without a
// key, or no provider URL stops it.
func workerCmd(ctx context.Context, log *slog.Logger, getenv func(string) string) error {
	llmCfg, err := llm.ConfigFromEnv(getenv)
	if err != nil {
		return err
	}
	url := getenv("DATABASE_URL")
	if url == "" {
		return errors.New("DATABASE_URL is not set")
	}
	providerURL := getenv("PROVIDER_URL")
	if providerURL == "" {
		return errors.New("PROVIDER_URL is not set (the mock provider, for example http://mockprovider:8091)")
	}
	schemas, err := schema.Load()
	if err != nil {
		return err
	}
	llmCfg.Schemas = schemas
	client, err := llm.New(llmCfg)
	if err != nil {
		return err
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	defer pool.Close()

	gen := &campaign.Generator{
		Pool:          pool,
		Schemas:       schemas,
		LLM:           client,
		Now:           time.Now,
		Rand:          rand.New(rand.NewPCG(rand.Uint64(), rand.Uint64())),
		Sleep:         sleep,
		DeltaInterval: campaign.DefaultDeltaInterval,
		Log:           log,
	}
	fanout := &delivery.FanoutWorker{DB: pool, Now: time.Now}
	send := &delivery.SendWorker{
		DB:              pool,
		ProviderURL:     providerURL,
		Limiters:        delivery.NewLimiters(),
		ProviderTimeout: delivery.ProviderTimeout,
		Now:             time.Now,
		Backoff:         delivery.RandomBackoff(rand.New(rand.NewPCG(rand.Uint64(), rand.Uint64()))),
		Client:          &http.Client{},
		Log:             log,
	}
	workers := river.NewWorkers()
	river.AddWorker(workers, campaign.NewGenerateWorker(gen))
	river.AddWorker(workers, fanout)
	river.AddWorker(workers, send)
	rc, err := river.NewClient(riverpgxv5.New(pool), jobs.ClientConfig(workers, log))
	if err != nil {
		return err
	}
	fanout.Jobs = rc
	if err := rc.Start(ctx); err != nil {
		return err
	}
	// Never log the key; only whether it is there.
	log.Info("worker started", "llm_mode", getenv("LLM_MODE"), "model", client.Model(), "anthropic_key", keyState(getenv("LLM_MODE")))
	<-ctx.Done()
	stop, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	return rc.Stop(stop)
}

func keyState(mode string) string {
	if mode == "anthropic" {
		return "present" // ConfigFromEnv refused to start without one
	}
	return "not used"
}

// sleep waits for d or until ctx ends.
func sleep(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// mockllmCmd serves the fake Messages API for LLM_MODE=mock. It needs no
// database and no key.
func mockllmCmd(ctx context.Context, log *slog.Logger, getenv func(string) string) error {
	addr := getenv("MOCKLLM_ADDR")
	if addr == "" {
		addr = ":8090"
	}
	hs := &http.Server{Addr: addr, Handler: mockllmHandler(getenv), ReadHeaderTimeout: 5 * time.Second}
	return serve(ctx, log, hs, "mockllm listening")
}

func mockllmHandler(getenv func(string) string) *mockllm.Server {
	return mockllm.New(mockllm.Options{InvalidFirst: getenv("MOCKLLM_INVALID_FIRST") == "true"})
}

// serve runs hs until ctx ends, then shuts it down.
func serve(ctx context.Context, log *slog.Logger, hs *http.Server, msg string) error {
	go func() {
		<-ctx.Done()
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = hs.Shutdown(shutdown)
	}()
	log.Info(msg, "addr", hs.Addr)
	if err := hs.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

