1	package delivery
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"log/slog"
11		"math/rand/v2"
12		"net/http"
13		"strings"
14		"sync"
15		"time"
16	
17		"github.com/riverqueue/river"
18	
19		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/campaign"
20		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/content"
21		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/jobs"
22		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/retry"
23		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
24	)
25	
26	// Send limits (rule 6).
27	const (
28		ProviderTimeout = 5 * time.Second // per attempt
29		MaxAttempts     = 6               // then the message is dead
30		MaxAge          = 15 * time.Minute
31	)
32	
33	// SendWorker sends one message per job, on the sms and email queues.
34	type SendWorker struct {
35		river.WorkerDefaults[jobs.SendArgs]
36		DB              DB
37		ProviderURL     string
38		Limiters        map[string]Limiter // one per channel; every attempt takes a token
39		ProviderTimeout time.Duration
40		Now             func() time.Time
41		// Backoff gives the delay before retry number n (0 is the first retry),
42		// when the provider sent no Retry-After.
43		Backoff func(retry int) time.Duration
44		Client  *http.Client
45		Log     *slog.Logger
46	}
47	
48	// RandomBackoff is retry.Backoff over a shared, locked random source.
49	func RandomBackoff(rng *rand.Rand) func(int) time.Duration {
50		var mu sync.Mutex
51		return func(n int) time.Duration {
52			mu.Lock()
53			defer mu.Unlock()
54			return retry.Backoff(n, rng)
55		}
56	}
57	
58	// Timeout bounds one job run.
59	func (w *SendWorker) Timeout(*river.Job[jobs.SendArgs]) time.Duration { return jobs.SendTimeout }
60	
61	func (w *SendWorker) log() *slog.Logger {
62		if w.Log != nil {
63			return w.Log
64		}
65		return slog.New(slog.DiscardHandler)
66	}
67	
68	// Work sends a message at least once. Every state update is guarded by its
69	// predecessors. Retries carry the message id as the idempotency key, so the
70	// provider sends once however often this runs. A retryable failure snoozes
71	// the job; a permanent one fails the message and cancels the job; a
72	// database error is returned, so River runs the job again and the message,
73	// still in sending, is reclaimed.
74	func (w *SendWorker) Work(ctx context.Context, job *river.Job[jobs.SendArgs]) error {
75		id := job.Args.MessageID
76		log := w.log().With("message_id", id)
77		m, err := store.LoadSend(ctx, w.DB, id)
78		if errors.Is(err, store.ErrNotFound) {
79			return river.JobCancel(fmt.Errorf("send: message %s does not exist", id))
80		}
81		if err != nil {
82			return err
83		}
84		if m.State != "queued" && m.State != "sending" {
85			return nil // terminal: never sent again
86		}
87		if campaign.State(m.CampaignState) == campaign.Cancelled {
88			return w.skip(ctx, log, m, "cancelled")
89		}
90		if !m.Consent {
91			return w.skip(ctx, log, m, "no_consent")
92		}
93	
94		lim := w.Limiters[m.Channel]
95		if lim == nil {
96			return fmt.Errorf("send: no limiter for channel %q", m.Channel)
97		}
98		if err := lim.Wait(ctx); err != nil {
99			return err
100		}
101		now := w.Now()
102		attempts, first, ok, err := store.ClaimMessage(ctx, w.DB, id, now)
103		if err != nil || !ok {
104			return err // !ok: another run finished it
105		}
106		payload, err := w.payload(m)
107		if err != nil {
108			// A template the validator let through but the renderer rejects.
109			if _, uerr := store.MarkFinal(ctx, w.DB, id, "failed", string(retry.ClientError), "render: "+err.Error()); uerr != nil {
110				return uerr
111			}
112			return w.finish(ctx, log, m, river.JobCancel(err))
113		}
114		providerID, res, lastErr := w.post(ctx, id, payload)
115		now = w.Now()
116		switch {
117		case res.Class == retry.Success:
118			if _, err := store.MarkSent(ctx, w.DB, id, providerID, now); err != nil {
119				return err
120			}
121			log.Info("message sent", "channel", m.Channel, "attempts", attempts)
122			return w.finish(ctx, log, m, nil)
123	
124		case !res.Class.Retryable():
125			if _, err := store.MarkFinal(ctx, w.DB, id, "failed", string(res.Class), lastErr); err != nil {
126				return err
127			}
128			log.Warn("message failed", "channel", m.Channel, "class", res.Class, "attempts", attempts)
129			return w.finish(ctx, log, m, river.JobCancel(fmt.Errorf("send: %s", lastErr)))
130	
131		case attempts >= MaxAttempts || now.Sub(first) >= MaxAge:
132			if _, err := store.MarkFinal(ctx, w.DB, id, "dead", string(res.Class), lastErr); err != nil {
133				return err
134			}
135			log.Warn("message dead", "channel", m.Channel, "class", res.Class, "attempts", attempts)
136			return w.finish(ctx, log, m, nil)
137		}
138	
139		delay := res.RetryAfter
140		if delay == 0 {
141			delay = w.Backoff(attempts - 1)
142		}
143		if _, err := store.MarkRetry(ctx, w.DB, id, string(res.Class), lastErr, now.Add(delay)); err != nil {
144			return err
145		}
146		log.Info("message retry", "channel", m.Channel, "class", res.Class, "attempts", attempts, "delay_ms", delay.Milliseconds())
147		return river.JobSnooze(delay)
148	}
149	
150	func (w *SendWorker) skip(ctx context.Context, log *slog.Logger, m store.Send, class string) error {
151		if _, err := store.SkipMessage(ctx, w.DB, m.ID, class); err != nil {
152			return err
153		}
154		log.Info("message skipped", "channel", m.Channel, "reason", class)
155		return w.finish(ctx, log, m, nil)
156	}
157	
158	// finish runs the completion check after a terminal update and returns ret.
159	func (w *SendWorker) finish(ctx context.Context, log *slog.Logger, m store.Send, ret error) error {
160		if err := campaign.CompleteIfDone(ctx, w.DB, m.CampaignID); err != nil {
161			log.Error("completion check failed", "campaign_id", m.CampaignID, "error", err)
162			return err
163		}
164		return ret
165	}
166	
167	type providerMessage struct {
168		Channel string `json:"channel"`
169		To      string `json:"to"`
170		Subject string `json:"subject,omitempty"`
171		Body    string `json:"body"`
172	}
173	
174	// payload renders the message. The renderer gets a RenderContext, never the
175	// users row; contact data goes only to "to".
176	func (w *SendWorker) payload(m store.Send) ([]byte, error) {
177		rc := content.RenderContext{FirstName: m.FirstName, LastName: m.LastName, City: m.City, CampaignURL: m.CampaignURL}
178		pm := providerMessage{Channel: m.Channel}
179		var err error
180		if m.Channel == "sms" {
181			pm.To = m.Phone
182			pm.Body, err = content.RenderText(m.SMSBody, rc)
183		} else {
184			pm.To = m.Email
185			if pm.Subject, err = content.RenderText(m.EmailSubject, rc); err == nil {
186				pm.Body, err = content.RenderEmailHTML(m.EmailBody, rc)
187			}
188		}
189		if err != nil {
190			return nil, err
191		}
192		return json.Marshal(pm)
193	}
194	
195	// post makes one provider call with the message id as the idempotency key.
196	// lastErr describes a failure without any message content.
197	func (w *SendWorker) post(ctx context.Context, id string, payload []byte) (providerID string, res retry.Result, lastErr string) {
198		timeout := w.ProviderTimeout
199		if timeout <= 0 {
200			timeout = ProviderTimeout
201		}
202		ctx, cancel := context.WithTimeout(ctx, timeout)
203		defer cancel()
204		req, err := http.NewRequestWithContext(ctx, http.MethodPost, strings.TrimRight(w.ProviderURL, "/")+"/v1/messages", bytes.NewReader(payload))
205		if err != nil {
206			return "", retry.Result{Class: retry.ClientError}, "request: " + err.Error()
207		}
208		req.Header.Set("Content-Type", "application/json")
209		req.Header.Set("Idempotency-Key", id)
210		// net/http treats a request with an Idempotency-Key as replayable and
211		// silently resends it on a dropped connection. That call would take no
212		// limiter token and count no attempt. Without GetBody the transport
213		// cannot replay it, so every retry goes through Work.
214		req.GetBody = nil
215		client := w.Client
216		if client == nil {
217			client = http.DefaultClient
218		}
219		resp, err := client.Do(req)
220		if err != nil {
221			res := retry.Classify(nil, err, time.Now())
222			return "", res, fmt.Sprintf("provider call failed: %s", res.Class)
223		}
224		defer resp.Body.Close()
225		body, err := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
226		if err != nil {
227			res := retry.Classify(nil, err, time.Now())
228			return "", res, fmt.Sprintf("reading the provider answer failed: %s", res.Class)
229		}
230		res = retry.Classify(resp, nil, time.Now())
231		if res.Class != retry.Success {
232			return "", res, fmt.Sprintf("provider answered %d", resp.StatusCode)
233		}
234		var out struct {
235			ID string `json:"id"`
236		}
237		if err := json.Unmarshal(body, &out); err != nil || out.ID == "" {
238			// Sent, but we cannot tell the id: retry, the replay will carry it.
239			return "", retry.Result{Class: retry.ServerError}, "provider answered without an id"
240		}
241		return out.ID, res, ""
242	}
243

1	package content
2	
3	import (
4		"bytes"
5		"cmp"
6		"fmt"
7		"regexp"
8		"slices"
9		"strings"
10		"unicode/utf8"
11	
12		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
13		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
14	)
15	
16	// Rendered length limits (runes, worst case). They match the maxLength of the
17	// raw templates in schemas/content.schema.json; content_test.go checks that.
18	const (
19		SMSMaxChars     = 160
20		SubjectMaxChars = 80
21	)
22	
23	// Content is validated copy.
24	type Content struct {
25		SMSBody      string
26		EmailSubject string
27		EmailBody    string
28		// SMS is the pessimistic estimate: longest variable values, and Turkish
29		// letters in names and city.
30		SMS SMSInfo
31	}
32	
33	// Banned patterns. They are checked on the text with every variable filled
34	// in by a placeholder, so "{{city}}.com" is caught too. {{campaign_url}} is
35	// the one allowed link and is filled with a space.
36	var (
37		schemeRe = regexp.MustCompile(`(?i)[a-z][a-z0-9+.\-]*://|www\.`)
38		// A bare domain: dot-separated labels ending in a common TLD. Labels are
39		// Unicode-aware, so a Cyrillic lookalike such as "іnsider.com" is caught.
40		domainRe = regexp.MustCompile(`(?i)(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+` +
41			`(?:com|net|org|info|biz|io|co|ai|app|dev|me|ly|gl|to|cc|tv|xyz|link|shop|store|site|online|tr|eu|uk|de|us))(?:$|[^\p{L}\p{N}_-])`)
42		// A domain with any TLD, given away by the path that follows it, such as
43		// "evil.top/login". The TLD starts with a letter, so "10.30/11" passes.
44		domainPathRe = regexp.MustCompile(`(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+\p{L}[\p{L}\p{N}-]+/)`)
45		// What may touch {{campaign_url}}. Anything else could extend the link
46		// into another one: "{{campaign_url}}@evil.top", "{{campaign_url}}.evil.com".
47		// Before it: the start or white space, then opening punctuation.
48		// After it: closing punctuation, then white space or the end.
49		urlBeforeRe = regexp.MustCompile(`(?:^|[\s\p{Z}])[(\["'“‘«:]*$`)
50		urlAfterRe  = regexp.MustCompile(`^[.,!?;:)\]"'”’»]*(?:[\s\p{Z}]|$)`)
51		ipRe        = regexp.MustCompile(`(?:^|[^\p{N}.])(\d{1,3}(?:\.\d{1,3}){3})(?:$|[^\p{N}.])`)
52		emailRe     = regexp.MustCompile(`[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+`)
53		htmlRe      = regexp.MustCompile(`<\s*/?\s*[A-Za-z][^>]*>`)
54	)
55	
56	// ValidateJSON parses and validates content given as raw JSON.
57	func ValidateJSON(set *schema.Set, data []byte) (Content, validation.Result) {
58		doc, err := schema.Decode(bytes.NewReader(data))
59		if err != nil {
60			var res validation.Result
61			res.Error("", validation.InvalidJSON, err.Error())
62			return Content{}, res
63		}
64		return Validate(set, doc)
65	}
66	
67	// Validate checks decoded content (from schema.Decode): the schema first,
68	// then templates, banned links, emails and HTML, and the worst-case rendered
69	// length. Every problem is reported. SMS encoding and segment count are
70	// warnings only.
71	func Validate(set *schema.Set, doc any) (Content, validation.Result) {
72		var res validation.Result
73		rawTooLong := map[string]bool{}
74		if err := set.Validate(schema.Content, doc); err != nil {
75			for _, is := range schema.Issues(err, "") {
76				res.Errors = append(res.Errors, is)
77				if is.Code == validation.TooLong {
78					rawTooLong[is.Path] = true
79				}
80			}
81		}
82	
83		fields := []struct {
84			path, a, b string
85			limit      int
86		}{
87			{"/sms/body", "sms", "body", SMSMaxChars},
88			{"/email/subject", "email", "subject", SubjectMaxChars},
89			{"/email/body", "email", "body", 0},
90		}
91		var smsParts []Part
92		values := map[string]string{}
93		for _, f := range fields {
94			s, ok := lookup(doc, f.a, f.b)
95			if !ok {
96				continue // the schema already reported it
97			}
98			values[f.path] = s
99			parts, issues := Parse(s)
100			for _, is := range issues {
101				res.Error(f.path, is.Code, is.Message)
102			}
103			checkBans(&res, f.path, parts)
104			if len(issues) > 0 {
105				continue // lengths of a broken template mean nothing
106			}
107			if f.limit > 0 && !rawTooLong[f.path] {
108				if n := utf8.RuneCountInString(worstCase(parts, false)); n > f.limit {
109					res.Error(f.path, validation.RenderedTooLong, fmt.Sprintf(
110						"can render up to %d characters with the longest variable values; the limit is %d", n, f.limit))
111				}
112			}
113			if f.path == "/sms/body" {
114				smsParts = parts
115			}
116		}
117	
118		var info SMSInfo
119		if smsParts != nil {
120			info = MeasureSMS(worstCase(smsParts, true))
121			if info.Segments > 1 {
122				msg := fmt.Sprintf("%s, %d segments in the worst case", info.Encoding, info.Segments)
123				if plain := MeasureSMS(worstCase(smsParts, false)); plain.Encoding != info.Encoding {
124					msg += fmt.Sprintf(" (names or city may contain Turkish letters such as ş, ğ, ı that switch the SMS to UCS-2; without them: %s, %d segment(s))", plain.Encoding, plain.Segments)
125				}
126				res.Warn("/sms/body", validation.SMSMultiSegment, msg)
127			}
128		}
129	
130		slices.SortStableFunc(res.Errors, func(a, b validation.Issue) int { return cmp.Compare(a.Path, b.Path) })
131		if !res.OK() {
132			return Content{}, res
133		}
134		return Content{
135			SMSBody:      values["/sms/body"],
136			EmailSubject: values["/email/subject"],
137			EmailBody:    values["/email/body"],
138			SMS:          info,
139		}, res
140	}
141	
142	// checkBans reports links, email addresses and HTML in the literal text.
143	func checkBans(res *validation.Result, path string, parts []Part) {
144		text := fill(parts)
145		if urlTouched(parts) {
146			res.Error(path, validation.URLNotAllowed, "text directly next to {{campaign_url}} is not allowed; put a space around it")
147		} else if m := schemeRe.FindString(text); m != "" {
148			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m))
149		} else if m := domainRe.FindStringSubmatch(text); m != nil {
150			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("domain %q is not allowed; use {{campaign_url}}", m[1]))
151		} else if m := domainPathRe.FindStringSubmatch(text); m != nil {
152			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m[1]))
153		} else if m := ipRe.FindStringSubmatch(text); m != nil {
154			res.Error(path, validation.URLNotAllowed, fmt.Sprintf("address %q is not allowed; use {{campaign_url}}", m[1]))
155		}
156		if m := emailRe.FindString(text); m != "" {
157			res.Error(path, validation.EmailNotAllowed, fmt.Sprintf("email address %q is not allowed", m))
158		}
159		if m := htmlRe.FindString(text); m != "" {
160			res.Error(path, validation.HTMLNotAllowed, fmt.Sprintf("HTML %q is not allowed; copy is plain text", m))
161		}
162	}
163	
164	// fill joins the parts with a placeholder for each variable: a space for
165	// {{campaign_url}}, an "x" for the others.
166	func fill(parts []Part) string {
167		var b strings.Builder
168		for _, p := range parts {
169			switch p.Var {
170			case "":
171				b.WriteString(p.Text)
172			case "campaign_url":
173				b.WriteString(" ")
174			default:
175				b.WriteString("x")
176			}
177		}
178		return b.String()
179	}
180	
181	// urlTouched reports whether any {{campaign_url}} has text attached to it.
182	func urlTouched(parts []Part) bool {
183		for i, p := range parts {
184			if p.Var == "campaign_url" &&
185				(!urlBeforeRe.MatchString(fill(parts[:i])) || !urlAfterRe.MatchString(fill(parts[i+1:]))) {
186				return true
187			}
188		}
189		return false
190	}
191	
192	func lookup(doc any, a, b string) (string, bool) {
193		m, _ := doc.(map[string]any)
194		inner, _ := m[a].(map[string]any)
195		s, ok := inner[b].(string)
196		return s, ok
197	}
