29	// WorkerActor is the actor of transitions the generate job makes.
30	const WorkerActor = "worker"
31	
32	// Retry limits per stage (rule 5, rule 6). They are counted separately: a
33	// transport failure does not use up a validation attempt.
34	const (
35		MaxValidationAttempts = 3
36		MaxTransportRetries   = 3
37	)
38	
39	// DefaultDeltaInterval is how often streamed copy is written to the event
40	// log, per field. The worker sets it; zero writes every delta.
41	const DefaultDeltaInterval = 150 * time.Millisecond
42	
43	// Reasons in the failed event and in the audit trail.
44	const (
45		ReasonRefusal       = "refusal"
46		ReasonInvalidOutput = "invalid_output"
47		ReasonTransport     = "transport_error"
48		ReasonCancelled     = "cancelled"
49	)
50	
51	// LLM is what the generator needs from the model client. *llm.Client
52	// satisfies it.
53	type LLM interface {
54		Call(ctx context.Context, conv *llm.Conversation, onText func(string)) (llm.Response, error)
55		Model() string
56	}
57	
58	// Pool is a database with transactions. *pgxpool.Pool satisfies it.
59	type Pool interface {
60		Beginner
61		store.DB
62	}
63	
64	// Generator runs the generate job: the segment stage, then the content
65	// stage, each validated and repaired, and records every call and event.
66	type Generator struct {
67		Pool    Pool
68		Schemas *schema.Set
69		LLM     LLM
70		Now     func() time.Time // the asOf of audience counts
71		Rand    *rand.Rand       // backoff jitter; shared, so guarded by mu
72		Sleep   func(ctx context.Context, d time.Duration) error
73		// DeltaInterval batches streamed copy per field (DefaultDeltaInterval
74		// in the worker). Zero writes every delta.
75		DeltaInterval time.Duration
76		Log           *slog.Logger
77	
78		mu sync.Mutex
79	}
80	
81	// errStop means the campaign is no longer generating at the job's version
82	// (cancelled, or a newer generation started): the job stops and writes
83	// nothing more.
84	var errStop = errors.New("campaign: generation no longer current")
85	
86	// Run runs one generation. A failed generation is an outcome, written to
87	// the campaign; Run returns an error only when the job itself could not do
88	// its work (a database error, or the context ended while the campaign was
89	// still generating), so River can retry it.
90	func (g *Generator) Run(ctx context.Context, args jobs.GenerateArgs) error {
91		r := &genRun{g: g, id: args.CampaignID, version: args.Version}
92		err := r.run(ctx)
93		if errors.Is(err, errStop) {
94			return nil
95		}
96		if err != nil && ctx.Err() != nil {
97			// River cancelled the job, or the worker is shutting down. If the
98			// campaign moved on, there is nothing left to do.
99			if ok, cerr := r.current(context.WithoutCancel(ctx)); cerr == nil && !ok {
100				return nil
101			}
102		}
103		return err
104	}
105	
106	type genRun struct {
107		g       *Generator
108		id      string
109		version int
110	}
111	
112	func (r *genRun) log() *slog.Logger {
113		if r.g.Log != nil {
114			return r.g.Log
115		}
116		return slog.New(slog.DiscardHandler)
117	}
118	
119	// current reports whether the campaign is still generating at the version.
120	func (r *genRun) current(ctx context.Context) (bool, error) {
121		return store.LockGenerating(ctx, r.g.Pool, r.id, r.version)
122	}
123	
124	// write runs fn in a transaction that holds the campaign row, only while the
125	// generation is current. Otherwise it returns errStop and writes nothing.
126	func (r *genRun) write(ctx context.Context, fn func(pgx.Tx) error) error {
127		return inTx(ctx, r.g.Pool, func(tx pgx.Tx) error {
128			ok, err := store.LockGenerating(ctx, tx, r.id, r.version)
129			if err != nil {
130				return err
131			}
132			if !ok {
133				return errStop
134			}
135			return fn(tx)
136		})
137	}
138	
139	func (r *genRun) event(ctx context.Context, typ string, payload any) error {
140		return r.write(ctx, func(tx pgx.Tx) error {
141			_, err := store.InsertGenerationEvent(ctx, tx, r.id, typ, payload)
142			return err
143		})
144	}
145	
146	func (r *genRun) run(ctx context.Context) error {
147		c, err := store.GetCampaign(ctx, r.g.Pool, r.id)
148		if errors.Is(err, store.ErrNotFound) {
149			return errStop
150		}
151		if err != nil {
152			return err
153		}
154		if State(c.State) != Generating || c.Version != r.version {
155			return errStop
156		}
157		asOf := r.g.Now().UTC().Truncate(time.Microsecond)
158	
159		// Segment stage.
160		var rule segment.Rule
161		var ruleDoc any
162		var segWarnings []validation.Issue
163		out, err := r.stage(ctx, llm.NewConversation(llm.Segment, llm.SegmentTurn(c.Brief)), func(text string) validation.Result {
164			doc, derr := schema.Decode(strings.NewReader(text))
165			if derr != nil {
166				var res validation.Result
167				res.Error("", validation.InvalidJSON, "the answer is not one JSON value: "+derr.Error())
168				return res
169			}
170			var res validation.Result
171			rule, res = segment.Validate(r.g.Schemas, doc)
172			ruleDoc, segWarnings = doc, res.Warnings
173			return res
174		}, nil)
175		if err != nil || out != nil {
176			return r.finish(ctx, err, out)
177		}
178		counts, err := segment.CountAudience(ctx, r.g.Pool, rule, asOf)
179		if err != nil {
180			return err
181		}
182		description := segment.Describe(rule)
183		if err := r.event(ctx, "segment_ready", map[string]any{"rule": ruleDoc, "description": description, "counts": counts}); err != nil {
184			return err
185		}
186	
187		// Content stage, streamed.
188		var cont content.Content
189		var contWarnings []validation.Issue
190		out, err = r.stage(ctx, llm.NewConversation(llm.Content, llm.ContentTurn(c.Brief, description)), func(text string) validation.Result {
191			var res validation.Result
192			cont, res = content.ValidateJSON(r.g.Schemas, []byte(text))
193			contWarnings = res.Warnings
194			return res
195		}, r.newDeltas)
196		if err != nil || out != nil {
197			return r.finish(ctx, err, out)
198		}
199	
200		// Success: the revision, the transition and the done event together.
201		segJSON, err := json.Marshal(ruleDoc)
202		if err != nil {
203			return err
204		}
205		warnings := []validation.Issue{}
206		for _, w := range segWarnings {
207			warnings = append(warnings, validation.Issue{Path: "/segment" + w.Path, Code: w.Code, Message: w.Message})
208		}
209		for _, w := range contWarnings {
210			warnings = append(warnings, validation.Issue{Path: "/content" + w.Path, Code: w.Code, Message: w.Message})
211		}
212		warnJSON, err := json.Marshal(warnings)
213		if err != nil {
214			return err
215		}
216		return r.write(ctx, func(tx pgx.Tx) error {
217			if err := Transition(ctx, tx, Move{ID: r.id, From: Generating, To: InReview, Version: r.version, Actor: WorkerActor, Reason: "generated"}); err != nil {
218				return err
219			}
220			rev, err := store.InsertRevision(ctx, tx, store.NewRevision{
221				CampaignID: r.id, Source: "llm", Segment: segJSON,
222				SMSBody: cont.SMSBody, EmailSubject: cont.EmailSubject, EmailBody: cont.EmailBody,
223				Warnings: warnJSON, AudienceTotal: counts.Total, SMSEligible: counts.SMSEligible, EmailEligible: counts.EmailEligible,
224			})
225			if err != nil {
226				return err
227			}
228			_, err = store.InsertGenerationEvent(ctx, tx, r.id, "done", map[string]any{"revision_id": rev.ID})
229			return err
230		})
231	}
