2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"net/http"
9		"strconv"
10		"sync"
11		"time"
12	
13		"github.com/jackc/pgx/v5/pgxpool"
14	
15		"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
16	)
17	
18	// Defaults of the event stream.
19	const (
20		DefaultHeartbeat    = 15 * time.Second
21		DefaultPollInterval = time.Second // covers a missed notification
22	)
23	
24	// Hub fans out generation event notifications. One LISTEN connection per
25	// api process feeds it, so streams do not each hold a database connection.
26	type Hub struct {
27		mu   sync.Mutex
28		subs map[string]map[chan struct{}]struct{}
29	}
30	
31	// NewHub starts listening on pool until ctx ends. A lost connection is
32	// reopened after a pause; streams also poll, so nothing is lost meanwhile.
33	func NewHub(ctx context.Context, pool *pgxpool.Pool, log *slog.Logger) *Hub {
34		h := &Hub{subs: map[string]map[chan struct{}]struct{}{}}
35		go h.listen(ctx, pool, log)
36		return h
37	}
38	
39	func (h *Hub) listen(ctx context.Context, pool *pgxpool.Pool, log *slog.Logger) {
40		for ctx.Err() == nil {
41			err := h.listenOnce(ctx, pool)
42			if ctx.Err() != nil {
43				return
44			}
45			log.Warn("event hub: listen failed; retrying", "error", err)
46			select {
47			case <-ctx.Done():
48				return
49			case <-time.After(time.Second):
50			}
51		}
52	}
53	
54	func (h *Hub) listenOnce(ctx context.Context, pool *pgxpool.Pool) error {
55		pc, err := pool.Acquire(ctx)
56		if err != nil {
57			return err
58		}
59		// The connection is in LISTEN state; never hand it back to the pool.
60		conn := pc.Hijack()
61		defer conn.Close(context.WithoutCancel(ctx))
62		if _, err := conn.Exec(ctx, "LISTEN "+store.GenerationEventsChannel); err != nil {
63			return err
64		}
65		for {
66			n, err := conn.WaitForNotification(ctx)
67			if err != nil {
68				return err
69			}
70			h.notify(n.Payload)
71		}
72	}
73	
74	func (h *Hub) notify(campaignID string) {
75		h.mu.Lock()
76		defer h.mu.Unlock()
77		for ch := range h.subs[campaignID] {
78			select {
79			case ch <- struct{}{}:
80			default: // a wake-up is already pending
81			}
82		}
83	}
84	
85	// Subscribe returns a channel that is signalled when the campaign may have
86	// new events, and a function to unsubscribe.
87	func (h *Hub) Subscribe(campaignID string) (<-chan struct{}, func()) {
88		ch := make(chan struct{}, 1)
89		h.mu.Lock()
90		if h.subs[campaignID] == nil {
91			h.subs[campaignID] = map[chan struct{}]struct{}{}
92		}
93		h.subs[campaignID][ch] = struct{}{}
94		h.mu.Unlock()
95		return ch, func() {
96			h.mu.Lock()
97			defer h.mu.Unlock()
98			delete(h.subs[campaignID], ch)
99			if len(h.subs[campaignID]) == 0 {
100				delete(h.subs, campaignID)
101			}
102		}
103	}
104	
105	var errBadEventID = errors.New("expected a non-negative integer event id")
106	
107	func parseEventID(s string) (int64, error) {
108		n, err := strconv.ParseInt(s, 10, 64)
109		if err != nil || n < 0 {
110			return 0, errBadEventID
111		}
112		return n, nil
113	}
114	
115	// events streams a campaign's generation events as SSE: the stored backlog
116	// after Last-Event-ID (or ?after=), then live events, with heartbeat
117	// comments. It ends after a done or failed event. The token comes only from
118	// the Authorization header, so the browser reads this with fetch, not
119	// EventSource.
120	func (s *Server) events(w http.ResponseWriter, r *http.Request, id string) {
121		var after int64
122		for _, raw := range []string{r.URL.Query().Get("after"), r.Header.Get("Last-Event-ID")} {
123			if raw == "" {
124				continue
125			}
126			n, err := parseEventID(raw)
127			if err != nil {
128				writeError(w, http.StatusBadRequest, "invalid_event_id", err.Error())
129				return
130			}
131			after = max(after, n)
132		}
133		{
134			ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
135			_, err := store.GetCampaign(ctx, s.Pool, id)
136			cancel()
137			if err != nil {
138				s.fail(w, r, err)
139				return
140			}
141		}
142	
143		var wake <-chan struct{}
144		if s.Hub != nil {
145			ch, unsubscribe := s.Hub.Subscribe(id)
146			defer unsubscribe()
147			wake = ch
148		}
149		rc := http.NewResponseController(w)
150		// The server's WriteTimeout would cut a long stream.
151		_ = rc.SetWriteDeadline(time.Time{})
152		w.Header().Set("Content-Type", "text/event-stream")
153		w.Header().Set("Cache-Control", "no-cache")
154		w.Header().Set("X-Accel-Buffering", "no")
155		w.WriteHeader(http.StatusOK)
156		if rc.Flush() != nil {
157			return
158		}
159	
160		heartbeat := s.Heartbeat
161		if heartbeat <= 0 {
162			heartbeat = DefaultHeartbeat
163		}
164		poll := s.PollInterval
165		if poll <= 0 {
166			poll = DefaultPollInterval
167		}
168		hb, pt := time.NewTicker(heartbeat), time.NewTicker(poll)
169		defer hb.Stop()
170		defer pt.Stop()
171	
172		// send writes every new event and reports whether the stream is over.
173		send := func() (bool, error) {
174			ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
175			defer cancel()
176			list, err := store.ListGenerationEvents(ctx, s.Pool, id, after)
177			if err != nil {
178				return false, err
179			}
180			for _, e := range list {
181				if _, err := fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.ID, e.Type, e.Payload); err != nil {
182					return false, err
183				}
184				after = e.ID
185				if e.Type == "done" || e.Type == "failed" {
186					return true, rc.Flush()
187				}
188			}
189			return false, rc.Flush()
190		}
191		for {
192			ended, err := send()
193			if err != nil {
194				if r.Context().Err() == nil {
195					s.Log.Warn("event stream failed", "error", err, "request_id", requestIDFrom(r.Context()))
196				}
197				return
198			}
199			if ended {
200				return
201			}
202		wait:
203			select {
204			case <-r.Context().Done():
205				return
206			case <-hb.C:
207				if _, err := fmt.Fprint(w, ": heartbeat\n\n"); err != nil || rc.Flush() != nil {
208					return
209				}
210				goto wait
211			case <-wake:
212			case <-pt.C:
213			}
214		}
215	}
