391		e.prov.srv.Close()
392		c := insertSendingCampaign(t, e.pool)
393		id := insertMessage(t, e.pool, c, consentingUsers(t, e.pool, 1)[0], "sms", "")
394		if _, ok := snoozed(e.work(id)); !ok {
395			t.Fatal("not snoozed")
396		}
397		if m := loadMessage(t, e.pool, id); m.State != "queued" || str(m.LastErrorClass) != "conn_refused" || m.Attempts != 1 {
398			t.Errorf("message %+v; want queued, conn_refused, 1 attempt", m)
399		}
400		if e.tokensTaken() != 1 {
401			t.Errorf("%d tokens for one attempt", e.tokensTaken())
402		}
403	}
404	
405	// After the last terminal update the campaign completes, once.
406	func TestCampaignCompletion(t *testing.T) {
407		cases := []struct {
408			name   string
409			second string // forced outcome of the second message
410			want   string
411		}{
412			{"all sent", "ok", "completed"},
413			{"one failed", "400", "completed_with_failures"},
414		}
415		for _, cs := range cases {
416			t.Run(cs.name, func(t *testing.T) {
417				e := newSendEnv(t, mockprovider.Config{})
418				c := insertSendingCampaign(t, e.pool)
419				users := consentingUsers(t, e.pool, 2)
420				a := insertMessage(t, e.pool, c, users[0], "sms", "")
421				b := insertMessage(t, e.pool, c, users[1], "email", "")
422				e.prov.force(b, cs.second)
423	
424				if err := e.work(a); err != nil {
425					t.Fatal(err)
426				}
427				if state, _ := campaignState(t, e.pool, c.ID); state != "sending" {
428					t.Fatalf("one message left: campaign %s, want sending", state)
429				}
430				if err := e.work(b); err != nil && !cancelled(err) {
431					t.Fatal(err)
432				}
433				state, version := campaignState(t, e.pool, c.ID)
434				if state != cs.want || version != 4 {
435					t.Errorf("campaign %s version %d; want %s version 4", state, version, cs.want)
436				}
437				// A duplicate run of a finished job does not complete it again.
438				if err := e.work(a); err != nil {
439					t.Fatal(err)
440				}
441				want := []string{"sending>" + cs.want}
442				if got := auditTrail(t, e.pool, c.ID); !slices.Equal(got, want) {
443					t.Errorf("audit trail %v, want %v", got, want)
444				}
445			})
446		}
447	}
448	
449	// Skipped messages are not failures: a campaign whose last message lost its
450	// consent completes normally.
451	func TestCompletionCountsSkippedAsDone(t *testing.T) {
452		e := newSendEnv(t, mockprovider.Config{})
453		c := insertSendingCampaign(t, e.pool)
454		user := consentingUsers(t, e.pool, 1)[0]
455		id := insertMessage(t, e.pool, c, user, "sms", "")
456		if _, err := e.pool.Exec(context.Background(), `UPDATE users SET consent_sms = false WHERE id = $1`, user); err != nil {
457			t.Fatal(err)
458		}
459		if err := e.work(id); err != nil {
460			t.Fatal(err)
461		}
462		if state, _ := campaignState(t, e.pool, c.ID); state != "completed" {
463			t.Errorf("campaign %s, want completed", state)
464		}
465	}
466	
467	// A message whose id does not exist is a bug upstream; the job must not
468	// retry it forever.
469	func TestUnknownMessage(t *testing.T) {
470		e := newSendEnv(t, mockprovider.Config{})
471		err := e.work("00000000-0000-4000-8000-00000000dead")
472		if err != nil && !cancelled(err) {
473			t.Errorf("unknown message: %v; want nil or JobCancel", err)
474		}
475		if errors.Is(err, errCrash) || len(e.prov.all()) != 0 {
476			t.Error("an unknown message reached the provider")
477		}
478	}
