42	// appPool opens a seeded clone of the app database.
43	func appPool(t *testing.T) (*pgxpool.Pool, testdb.Seed) {
44		t.Helper()
45		url, meta := testdb.Seeded(t)
46		p, err := pgxpool.New(context.Background(), url)
47		if err != nil {
48			t.Fatal(err)
49		}
50		t.Cleanup(p.Close)
51		return p, meta
52	}
