54	// call is one request the provider received.
55	type call struct {
56		Key    string
57		Chaos  string // the X-Chaos the test forced, "" for none
58		Body   map[string]any
59		Status int // 0 when the connection was dropped or the client left
60	}
61	
62	// provider runs the real mock provider on its own database, behind a thin
63	// wrapper that records every request and can force outcomes per key with
64	// X-Chaos. Hooks let a test act while a request is in flight.
65	type provider struct {
66		URL   string
67		inner http.Handler
68		srv   *httptest.Server
69	
70		mu            sync.Mutex
71		script        map[string][]string
72		calls         []call
73		onRequest     func(key string) // before the provider handles the request
74		afterResponse func(key string) // after it wrote its answer
75	}
76	
77	func newProvider(t *testing.T, cfg mockprovider.Config) *provider {
78		t.Helper()
79		ctx := context.Background()
80		p, err := pgxpool.New(ctx, testdb.Fresh(t))
81		if err != nil {
82			t.Fatal(err)
83		}
84		t.Cleanup(p.Close)
85		if err := mockprovider.Migrate(ctx, p); err != nil {
86			t.Fatal(err)
87		}
88		cfg.ChaosHeader = true
89		pr := &provider{inner: mockprovider.New(p, cfg), script: map[string][]string{}}
90		pr.srv = httptest.NewServer(pr)
91		t.Cleanup(pr.srv.Close)
92		pr.URL = pr.srv.URL
93		return pr
94	}
95	
96	// force sets the X-Chaos of the next requests for key, in order. Requests
97	// past the script get no header ("" means the provider's own chaos).
98	func (p *provider) force(key string, chaos ...string) {
99		p.mu.Lock()
100		defer p.mu.Unlock()
101		p.script[key] = append(p.script[key], chaos...)
102	}
103	
104	func (p *provider) hooks(onRequest, afterResponse func(key string)) {
105		p.mu.Lock()
106		defer p.mu.Unlock()
107		p.onRequest, p.afterResponse = onRequest, afterResponse
108	}
109	
110	func (p *provider) all() []call {
111		p.mu.Lock()
112		defer p.mu.Unlock()
113		return append([]call(nil), p.calls...)
114	}
115	
116	func (p *provider) callsFor(key string) []call {
117		var out []call
118		for _, c := range p.all() {
119			if c.Key == key {
120				out = append(out, c)
121			}
122		}
123		return out
124	}
125	
126	func (p *provider) ServeHTTP(w http.ResponseWriter, r *http.Request) {
127		if r.URL.Path != "/v1/messages" {
128			p.inner.ServeHTTP(w, r)
129			return
130		}
131		body, _ := io.ReadAll(r.Body)
132		r.Body = io.NopCloser(bytes.NewReader(body))
133		key := r.Header.Get("Idempotency-Key")
134		var decoded map[string]any
135		_ = json.Unmarshal(body, &decoded)
136	
137		p.mu.Lock()
138		chaos := ""
139		if s := p.script[key]; len(s) > 0 {
140			chaos, p.script[key] = s[0], s[1:]
141		}
142		i := len(p.calls)
143		p.calls = append(p.calls, call{Key: key, Chaos: chaos, Body: decoded})
144		before, after := p.onRequest, p.afterResponse
145		p.mu.Unlock()
146	
147		r.Header.Del("X-Chaos") // only the test decides
148		if chaos != "" {
149			r.Header.Set("X-Chaos", chaos)
150		}
151		if before != nil {
152			before(key)
153		}
154		rec := &statusRecorder{ResponseWriter: w}
155		p.inner.ServeHTTP(rec, r)
156		p.mu.Lock()
157		p.calls[i].Status = rec.status
158		p.mu.Unlock()
159		if after != nil {
160			after(key)
161		}
162	}
