164	func (p *provider) stats(t *testing.T) mockprovider.Stats {
165		t.Helper()
166		resp, err := p.srv.Client().Get(p.URL + "/v1/stats")
167		if err != nil {
168			t.Fatal(err)
169		}
170		defer resp.Body.Close()
171		var s mockprovider.Stats
172		if err := json.NewDecoder(resp.Body).Decode(&s); err != nil {
173			t.Fatal(err)
174		}
175		return s
176	}
