178	// statusRecorder notes the status and still lets the provider hijack the
179	// connection for the drop mode.
180	type statusRecorder struct {
181		http.ResponseWriter
182		status int
183	}
184	
185	func (r *statusRecorder) WriteHeader(code int) {
186		if r.status == 0 {
187			r.status = code
188		}
189		r.ResponseWriter.WriteHeader(code)
190	}
191	
192	func (r *statusRecorder) Write(b []byte) (int, error) {
193		if r.status == 0 {
194			r.status = http.StatusOK
195		}
196		return r.ResponseWriter.Write(b)
197	}
198	
199	func (r *statusRecorder) Hijack() (net.Conn, *bufio.ReadWriter, error) {
200		return http.NewResponseController(r.ResponseWriter).Hijack()
201	}
202	
203	func (r *statusRecorder) Flush() { _ = http.NewResponseController(r.ResponseWriter).Flush() }
204	
205	func (r *statusRecorder) Unwrap() http.ResponseWriter { return r.ResponseWriter }
206	
207	// countingLimiter hands out tokens at once and counts them.
208	type countingLimiter struct{ n atomic.Int64 }
209	
210	func (c *countingLimiter) Wait(ctx context.Context) error {
211		c.n.Add(1)
212		return ctx.Err()
213	}
