215	var errCrash = errors.New("injected crash: the database is gone")
216	
217	// flakyDB is the app database until down is set. Then every call fails, as
218	// if the worker process died. It injects a crash between the provider call
219	// and the state update without a hook in the worker.
220	type flakyDB struct {
221		*pgxpool.Pool
222		down atomic.Bool
223	}
224	
225	func (d *flakyDB) Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error) {
226		if d.down.Load() {
227			return pgconn.CommandTag{}, errCrash
228		}
229		return d.Pool.Exec(ctx, sql, args...)
230	}
231	
232	func (d *flakyDB) Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error) {
233		if d.down.Load() {
234			return nil, errCrash
235		}
236		return d.Pool.Query(ctx, sql, args...)
237	}
