257	// sendEnv is a seeded app database, a mock provider and a send worker with
258	// a fixed clock, a fixed backoff and counting limiters.
259	type sendEnv struct {
260		pool    *pgxpool.Pool
261		asOf    time.Time
262		now     time.Time
263		prov    *provider
264		tokens  map[string]*countingLimiter
265		worker  *SendWorker
266		logs    *bytes.Buffer
267		retries []int // the retry numbers Backoff was called with
268		mu      sync.Mutex
269	}
