271	// fixedBackoff is what the test Backoff returns, so snoozes are exact.
272	const fixedBackoff = 3 * time.Second
273	
274	func newSendEnv(t *testing.T, cfg mockprovider.Config) *sendEnv {
275		t.Helper()
276		pool, meta := appPool(t)
277		e := &sendEnv{
278			pool:   pool,
279			asOf:   meta.AsOf,
280			now:    meta.AsOf.Add(time.Hour),
281			prov:   newProvider(t, cfg),
282			tokens: map[string]*countingLimiter{"sms": {}, "email": {}},
283			logs:   &bytes.Buffer{},
284		}
285		e.worker = &SendWorker{
286			DB:              pool,
287			ProviderURL:     e.prov.URL,
288			Limiters:        map[string]Limiter{"sms": e.tokens["sms"], "email": e.tokens["email"]},
289			ProviderTimeout: 300 * time.Millisecond,
290			Now:             func() time.Time { return e.now },
291			Backoff: func(retry int) time.Duration {
292				e.mu.Lock()
293				defer e.mu.Unlock()
294				e.retries = append(e.retries, retry)
295				return fixedBackoff
296			},
297			Log: slog.New(slog.NewJSONHandler(&lockedWriter{w: e.logs}, &slog.HandlerOptions{Level: slog.LevelDebug})),
298		}
299		return e
300	}
