302	type lockedWriter struct {
303		mu sync.Mutex
304		w  io.Writer
305	}
306	
307	func (l *lockedWriter) Write(b []byte) (int, error) {
308		l.mu.Lock()
309		defer l.mu.Unlock()
310		return l.w.Write(b)
311	}
