418		t.Helper()
419		rows, err := p.Query(context.Background(), `SELECT coalesce(from_state::text, '') || '>' || to_state::text
420			FROM campaign_events WHERE campaign_id = $1 ORDER BY id`, id)
421		if err != nil {
