431	func sendJob(messageID string) *river.Job[jobs.SendArgs] {
432		return &river.Job[jobs.SendArgs]{
433			JobRow: &rivertype.JobRow{ID: 1, Attempt: 1, Kind: jobs.SendArgs{}.Kind(), State: rivertype.JobStateRunning},
434			Args:   jobs.SendArgs{MessageID: messageID},
435		}
