442	// snoozed reports the delay of a river.JobSnooze error.
443	func snoozed(err error) (time.Duration, bool) {
444		var s *river.JobSnoozeError
445		if errors.As(err, &s) {
446			return s.Duration, true
447		}
448		return 0, false
