16	func TestSendWorkerTimeout(t *testing.T) {
17		if got := (&SendWorker{}).Timeout(sendJob("x")); got != jobs.SendTimeout {
18			t.Errorf("job timeout %v, want %v", got, jobs.SendTimeout)
19		}
