28	// The happy path: one token, one request with the message id as the
29	// idempotency key, the rendered copy, and a sent row with the provider id.
30	func TestSendDeliversRenderedMessage(t *testing.T) {
31		e := newSendEnv(t, mockprovider.Config{})
32		c := insertSendingCampaign(t, e.pool)
33		user := consentingUsers(t, e.pool, 1)[0]
34		smsID := insertMessage(t, e.pool, c, user, "sms", "")
35		emailID := insertMessage(t, e.pool, c, user, "email", "")
36	
37		for _, id := range []string{smsID, emailID} {
38			if err := e.work(id); err != nil {
39				t.Fatalf("work %s: %v", id, err)
40			}
41		}
42	
43		var first, last, city, phone, email string
44		if err := e.pool.QueryRow(context.Background(), `SELECT first_name, last_name, city, phone, email FROM users WHERE id = $1`, user).
45			Scan(&first, &last, &city, &phone, &email); err != nil {
46			t.Fatal(err)
47		}
48		rc := content.RenderContext{FirstName: first, LastName: last, City: city, CampaignURL: campaignURL}
49		wantSMS, err := content.RenderText(smsBody, rc)
50		if err != nil {
51			t.Fatal(err)
52		}
53		wantSubject, err := content.RenderText(emailSubject, rc)
54		if err != nil {
55			t.Fatal(err)
56		}
57	
58		sms := e.prov.callsFor(smsID)
59		if len(sms) != 1 {
60			t.Fatalf("sms: %d requests, want 1", len(sms))
61		}
62		if b := sms[0].Body; b["channel"] != "sms" || b["to"] != phone || b["body"] != wantSMS {
63			t.Errorf("sms payload %v; want channel sms, to %q, body %q", b, phone, wantSMS)
64		}
65		if _, has := sms[0].Body["subject"]; has {
66			t.Errorf("sms payload has a subject: %v", sms[0].Body)
67		}
68		mail := e.prov.callsFor(emailID)
69		if len(mail) != 1 {
70			t.Fatalf("email: %d requests, want 1", len(mail))
71		}
72		if b := mail[0].Body; b["channel"] != "email" || b["to"] != email || b["subject"] != wantSubject || b["body"] == "" || b["body"] == nil {
73			t.Errorf("email payload %v; want channel email, to %q, subject %q and a body", b, email, wantSubject)
74		}
75	
76		for _, id := range []string{smsID, emailID} {
77			m := loadMessage(t, e.pool, id)
78			if m.State != "sent" || m.Attempts != 1 || str(m.ProviderID) == "" || m.SentAt == nil || m.FirstAttemptAt == nil {
79				t.Errorf("message %s: %+v; want sent after 1 attempt with a provider id", id, m)
80			}
81			if m.FirstAttemptAt != nil && !m.FirstAttemptAt.Equal(e.now) {
82				t.Errorf("first_attempt_at %v, want the worker's now %v", m.FirstAttemptAt, e.now)
83			}
84		}
85		if got := e.tokensTaken(); got != 2 {
86			t.Errorf("%d limiter tokens for 2 provider calls", got)
87		}
88		if e.tokens["sms"].n.Load() != 1 || e.tokens["email"].n.Load() != 1 {
89			t.Error("a message took its token from the other channel's limiter")
90		}
91		// No contact data or copy in the logs.
